PostMessage security.ejemplo:
// Emisor seguro
iframe.contentWindow.postMessage({ type: 'READY' }, 'https://widget.ejemplo.com');

// Receptor seguro
window.addEventListener('message', (event) => {
  if (event.origin !== 'https://app.ejemplo.com') return;
  if (event.data?.type === 'PING') handlePing();
});

Prototype pollution.ejemplo:
const BLOCKED_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function safeSet(target, key, value) {
  if (BLOCKED_KEYS.has(key) || !Object.prototype.hasOwnProperty.call(target, key) && key in Object.prototype) {
    return;
  }
  target[key] = value;
}

Sanitización de HTML.ejemplo:
import DOMPurify from 'dompurify';

const safeHtml = DOMPurify.sanitize(userHtml, {
  ALLOWED_TAGS: ['p', 'b', 'i', 'em', 'strong', 'a', 'ul', 'li'],
  ALLOWED_ATTR: ['href', 'target', 'rel']
});

