Trusted Types.ejemplo:
# Cabecera CSP exigiendo Trusted Types
Content-Security-Policy: require-trusted-types-for 'script'; trusted-types app-sanitizer;

// Política centralizada en JS
const policy = trustedTypes.createPolicy('app-sanitizer', {
  createHTML: (dirty) => DOMPurify.sanitize(dirty, { RETURN_TRUSTED_TYPE: true })
});

